T='''"use client";
import { useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const lesson = __DATA__;
export default function Demo({slug}:{slug:string}) {
  const [step,setStep]=useState(0);
  return <Lesson slug={slug} predict={{question:lesson.question,options:lesson.options,answer:lesson.answer}} exploreHint="Inspect the subject, then trace the evidence." minInteractions={2} reveal={()=><p>{lesson.explanation}</p>}>
    {({locked,interact})=><div><svg viewBox="0 0 340 190" className="stage-svg" role="img" aria-label={step === 0 ? "Evidence hidden until you explore." : step === 1 ? lesson.label : lesson.shownLabel}>
      {step === 0 && <text x="170" y="96" textAnchor="middle" fill="var(--muted)" fontSize="16">Evidence hidden</text>}
      {step >= 1 && <g>__BASE__</g>}
      {step >= 2 && <g>__MARK__</g>}
    </svg><Row><Control disabled={locked || step !== 0} onClick={()=>{setStep(1);interact();}}>Inspect the subject</Control><Control disabled={locked || step !== 1} onClick={()=>{setStep(2);interact();}}>Trace the evidence</Control></Row></div>}
  </Lesson>;
}
'''
for c in C:
    slug='zoo-herp-'+c['slug'];out=Path('src/demos/life')/slug
    if out.exists():raise ValueError(f'Existing lesson: {slug}')
    out.mkdir(parents=True)
    label=c['lim']; lesson={'question':c['q'],'options':c['options'],'answer':c['a'],'explanation':c['explain'],'label':label,'shownLabel':label+' '+c['explain']}
    demo=T.replace('__DATA__',json.dumps(lesson,ensure_ascii=False,indent=2)).replace('__BASE__',c['base']).replace('__MARK__',c['mark'])
    (out/'Demo.tsx').write_text(demo)
    source='Unverified starting points, not a verified citation for this claim: OpenStax Biology 2e https://openstax.org/books/biology-2e ; Smithsonian National Zoo https://nationalzoo.si.edu/animals . Exact claim-specific source and species qualifications require independent review.'
    meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals have structures and behaviors that can be investigated.'],'doesNotKnow':[c['explain']]},'misconception':'The evidence in the scenario supports a different interpretation.','objective':c['q'],'claims':[{'id':f'life.{slug}.c1','text':c['hook']+' '+c['q']+' '+c['explain'],'support':'source','source':source,'status':'unverified'},{'id':f'life.{slug}.c2','text':c['lim'],'support':'convention','source':'Drawing and stated scenario convention.','status':'unverified'},{'id':f'life.{slug}.c3','text':c['rq']+' '+c['rw'],'support':'source','source':source,'status':'unverified'}],'confidence':'','recall':{'question':c['rq'],'options':c['ro'],'answer':0,'why':c['rw']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
    (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
print('Generated',len(C),'drafts:',', '.join(str(c['n']) for c in C))
